//! Native positive-weight playlist selection, qualified against B1E1E0.
//! Event probability, owner/global state and native bank flag mapping stay upstream.
use crate::audio_random::NativeRandom;
use std::collections::VecDeque;
#[derive(Clone,Debug)]
pub struct Playlist {
 weights:Vec<u32>, weighted:bool, shuffle:bool, limit:usize,
 recent:VecDeque<usize>, visited:Vec<bool>, visited_count:usize,
}
#[derive(Debug,PartialEq)]
pub enum Error { UnsupportedWeights, UnsupportedCount }
impl Playlist {
 pub fn new(weights:Vec<u32>,weighted:bool,shuffle:bool,avoid:usize)->Result<Self,Error> {
  if weights.len()<2 || weights.len()>u16::MAX as usize {return Err(Error::UnsupportedCount);}
  if weights.contains(&0) || weights.iter().try_fold(0u32,|s,w|s.checked_add(*w)).is_none() {return Err(Error::UnsupportedWeights);}
  let n=weights.len();let limit=if shuffle {avoid.max(1)} else {avoid}.min(n-1);
  Ok(Self {weights,weighted,shuffle,limit,recent:VecDeque::new(),visited:vec![false;n],visited_count:0})
 }
 pub fn select(&mut self,rng:&mut NativeRandom)->usize {
  if self.visited_count==self.weights.len() {self.visited.fill(false);self.visited_count=0;}
  let eligible:Vec<_>=(0..self.weights.len()).filter(|i|!self.recent.contains(i)&&(!self.shuffle||!self.visited[*i])).collect();
  let mut ticket=if self.weighted {
   rng.weighted_rank(std::num::NonZeroU32::new(eligible.iter().map(|i|self.weights[*i]).sum()).expect("positive eligible weights"))
  } else {u32::from(rng.unweighted_rank(std::num::NonZeroU16::new(eligible.len() as u16).expect("eligible playlist")))};
  let chosen=eligible.into_iter().find(|i| {let weight=if self.weighted {self.weights[*i]} else {1};if ticket<weight {true} else {ticket-=weight;false}}).expect("bounded native ticket");
  if !self.visited[chosen] {self.visited[chosen]=true;self.visited_count+=1;}
  if self.limit>0 {self.recent.push_back(chosen);while self.recent.len()>self.limit {self.recent.pop_front();}}
  chosen
 }
}
