 #[test] fn unsupported_inputs_are_explicit() {
 assert_eq!(Playlist::new(vec![1,0],true,false,0).err(),Some(Error::UnsupportedWeights));
 assert_eq!(Playlist::new(vec![u32::MAX,1],true,false,0).err(),Some(Error::UnsupportedWeights));
 assert_eq!(Playlist::new(vec![1],false,false,0).err(),Some(Error::UnsupportedCount));
 }
